import{i as e}from"./index-CJ8x0t32.js";var t=e({food:()=>n}),n={bath:{eateries:[{id:`sally-lunns`,name:`Sally Lunn's Historic Eating House`,area:`Abbey Quarter (North Parade Passage)`,lat:51.38083,lng:-2.35804,kind:`cafe`,meals:[`breakfast`,`lunch`,`dinner`],spend:[8,25],order:[{name:`Sally Lunn bun with cinnamon butter`,price:8,note:`Half a giant brioche-style bun, toasted and spread with cinnamon butter`,wiki:`Sally Lunn bun`},{name:`Savoury Sally Lunn bun trencher`,note:`Bun half topped with a savoury dish such as Welsh rarebit or salmon`}],why:`One of the oldest houses in Bath, serving its namesake bun since the late 1600s, with a tiny kitchen museum in the cellar.`,tip:`Buns to take away are sold at the front counter with no wait. The cellar museum is free for diners.`,praise:[`A fun slice of Bath history in a creaky old house`,`Light, buttery buns with sweet and savoury options`,`Cosy rooms with a lot of period charm`],watchOut:`Queues at weekends and tight seating; it is firmly on the tourist trail.`,reservation:`recommended`,reservationNote:`Book for dinner or weekend lunch; daytime tea is often walk-in`},{id:`pump-room`,name:`The Pump Room`,area:`Abbey Quarter (Stall Street)`,lat:51.38137,lng:-2.35951,kind:`restaurant`,meals:[`breakfast`,`lunch`],spend:[15,45],order:[{name:`Afternoon tea`,price:40,note:`Sandwiches, scones with clotted cream and jam, and cakes on a tiered stand`,wiki:`Tea (meal)`},{name:`Cream tea`,price:14,note:`Scones with clotted cream and jam and a pot of tea`,wiki:`Cream tea`},{name:`A glass of spa water`,note:`Warm, mineral-rich water from the hot spring, poured from the fountain`}],why:`The grand Georgian salon above the Roman Baths, the social heart of Austen-era Bath, still serving tea to the sound of a pianist or trio.`,tip:`You can taste the warm spa water from the fountain; it is famously sulphurous.`,praise:[`Elegant Georgian room with chandeliers and live music`,`A classic, well-presented afternoon tea`,`Unique setting over the Roman Baths`],watchOut:`Expensive for what you get; you are paying largely for the setting.`,reservation:`recommended`,reservationNote:`Book afternoon tea online in advance, especially at weekends`},{id:`colonna-and-smalls`,name:`Colonna & Small's`,area:`Kingsmead (Chapel Row)`,lat:51.38279,lng:-2.36459,kind:`cafe`,meals:[`breakfast`],spend:[3,8],order:[{name:`Filter coffee of the day`,price:4,note:`Rotating single-origin coffee brewed by hand`},{name:`Flat white`,price:4,note:`Espresso with velvety steamed milk`,wiki:`Flat white`}],why:`Pioneering speciality coffee bar founded in 2009, with a constantly changing menu of beans and baristas happy to explain them.`,tip:`Daytime only; it is a short walk from Queen Square.`,praise:[`Exceptional, carefully brewed coffee`,`Knowledgeable, friendly baristas`,`Calm, simple space for a coffee break`],reservation:`walk-in`,reservationNote:`No bookings: order at the counter`},{id:`schwartz-bros`,name:`Schwartz Bros`,area:`City Centre (Saw Close)`,lat:51.38164,lng:-2.36239,kind:`casual`,meals:[`lunch`,`dinner`],spend:[9,16],order:[{name:`Blue cheese burger`,price:10,note:`Beef burger topped with melting blue cheese`,wiki:`Hamburger`},{name:`Thick milkshake`,note:`Old-fashioned, very thick shake`}],why:`Independent burger joint serving Bath for decades, loved by locals for juicy burgers, good fries and plenty of veggie options.`,tip:`Mostly takeaway; this branch is by the Theatre Royal, and there is another on Walcot Street.`,praise:[`Juicy, generous burgers at fair prices`,`Good choice of veggie burgers`,`Quick, friendly local favourite`],watchOut:`Little or no seating, so plan to eat on the go.`,reservation:`walk-in`,reservationNote:`No bookings: order at the counter`},{id:`the-raven`,name:`The Raven`,area:`Upper Town (Queen Street)`,lat:51.38318,lng:-2.36214,kind:`bar`,meals:[`lunch`,`dinner`],spend:[14,22],order:[{name:`Pie with mash and gravy`,price:15,note:`A Pieminister pie such as steak and ale, with mash, gravy and peas`,wiki:`Pie and mash`},{name:`Pint of local ale`,price:5,note:`Cask-conditioned ale from local and regional breweries`,wiki:`Real ale`}],why:`Traditional two-floor pub on a cobbled Georgian lane, best known for its pies and a well-kept range of real ales.`,tip:`Order at the bar. One of the few Bath pubs that serves food on Sunday evenings.`,praise:[`Hearty pies with plenty of gravy`,`Good choice of well-kept real ales`,`Cosy, buzzy traditional pub feel`],watchOut:`Gets packed in the evenings and on match days, and tables are hard to find.`,reservation:`walk-in`,reservationNote:`Order at the bar; grab a free table or try upstairs`},{id:`the-scallop-shell`,name:`The Scallop Shell`,area:`Kingsmead (Monmouth Place)`,lat:51.38292,lng:-2.36578,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[16,35],order:[{name:`Battered cod and chips`,price:17,note:`Cod in crisp batter with chips cut daily, mushy peas and tartare sauce`,wiki:`Fish and chips`},{name:`Grilled catch of the day`,note:`Whatever came in from the coast, simply cooked`}],why:`Relaxed fish restaurant and takeaway with the day's catch laid out on ice in an old roll-top bath; ordering is by ticking a paper menu.`,tip:`The takeaway counter is cheaper and quicker. The lunch deal on weekdays is good value.`,praise:[`Very fresh fish and light, crisp batter`,`Daily-changing seafood beyond fish and chips`,`Friendly, unfussy service`],watchOut:`Busy at peak times, and the dining room is noisy when full.`,reservation:`recommended`,reservationNote:`Book online for dinner and weekends; takeaway is walk-in`},{id:`sotto-sotto`,name:`Sotto Sotto`,area:`Abbey Quarter (North Parade)`,lat:51.38052,lng:-2.35662,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[30,50],order:[{name:`Homemade pasta of the day`,note:`Fresh pasta such as fettuccine with slow-cooked lamb ragù`},{name:`Penne alla vodka`,note:`Penne in a creamy tomato and vodka sauce`,wiki:`Penne alla vodka`}],why:`Candlelit Italian restaurant in a vaulted Georgian cellar, a long-time favourite in the city for romantic dinners.`,tip:`Ask for a table in one of the arched alcoves.`,praise:[`Atmospheric candlelit vaulted cellar`,`Well-made, generous Italian dishes`,`Warm, attentive staff`],watchOut:`Can feel cramped and loud on busy nights.`,reservation:`essential`,reservationNote:`Book ahead for any evening, a week or more for Friday and Saturday`},{id:`the-circus-restaurant`,name:`The Circus Restaurant`,area:`Royal Crescent (Brock Street)`,lat:51.38623,lng:-2.36497,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[30,55],order:[{name:`Seasonal set lunch`,note:`Short menu of modern British dishes using West Country produce`},{name:`Dish of the season`,note:`The menu changes with the seasons, from lamb to local game`}],why:`Family-run restaurant in a Georgian house between the Circus and the Royal Crescent, cooking seasonal West Country produce.`,tip:`Closed Sundays. Lunch is better value than dinner.`,praise:[`Thoughtful seasonal cooking`,`Charming Georgian setting near the Crescent`,`Relaxed, personal service`],reservation:`recommended`,reservationNote:`Booking advised year-round, especially for dinner`}],dishes:{"Sally Lunn Bun":{price:[6,12],wiki:`Sally Lunn bun`},"Bath Bun":{price:[2,4],wiki:`Bath bun`},"Cream Tea":{price:[9,15],wiki:`Cream tea`},"Fish and Chips":{price:[11,20],wiki:`Fish and chips`},"Pie and Mash":{price:[13,18],wiki:`Pie and mash`},"Ploughman's Lunch":{price:[10,15],wiki:`Ploughman's lunch`}}}},r=e({food:()=>i}),i={cotswolds:{eateries:[{id:`huffkins-stow`,name:`Huffkins Stow-on-the-Wold`,area:`Stow-on-the-Wold (The Square)`,lat:51.93041,lng:-1.72335,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[8,25],order:[{name:`Cream tea`,price:12,note:`Freshly baked scones with clotted cream, jam and a pot of tea`,wiki:`Cream tea`},{name:`Lardy cake`,note:`A rich, sticky traditional Cotswold bread with dried fruit`,wiki:`Lardy cake`}],why:`Branch of a Cotswold family bakery founded in Burford in 1890, serving teas, light lunches and home-baked cakes in an old house on the square.`,tip:`Pick up a lardy cake or loaf from the bakery counter for a picnic.`,praise:[`Good scones and generous cream teas`,`Cosy old rooms right on the square`,`Handy for breakfast before exploring`],watchOut:`Small and busy at weekends, so there can be a wait for a table.`,reservation:`walk-in`,reservationNote:`Mostly walk-in; afternoon tea can be booked ahead`},{id:`old-stocks-inn`,name:`The Old Stocks Inn`,area:`Stow-on-the-Wold (The Square)`,lat:51.93091,lng:-1.72263,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[25,50],order:[{name:`Seasonal modern British main`,note:`Local lamb, pork or fish, cooked with Cotswold produce`},{name:`Sunday roast`,price:24,note:`Roast meat with Yorkshire pudding, roast potatoes and gravy`,wiki:`Sunday roast`}],why:`A 17th-century inn on the market square, smartly restored, serving seasonal, locally sourced cooking alongside a relaxed bar.`,tip:`The bar has a lighter menu and takes walk-ins; the Sunday lunch is popular.`,praise:[`Careful seasonal cooking with local produce`,`Stylish rooms inside an old coaching inn`,`Welcoming to dogs in the bar`],watchOut:`Prices are on the high side, as in much of Stow.`,reservation:`recommended`,reservationNote:`Book online for dinner and Sunday lunch`},{id:`bakery-on-the-water`,name:`Bakery on the Water`,area:`Bourton-on-the-Water (Sherborne Street)`,lat:51.88447,lng:-1.75893,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[5,15],order:[{name:`Scone with clotted cream`,price:6,note:`Freshly baked scone with clotted cream and jam`,wiki:`Scone`},{name:`Pastry or sausage roll`,note:`Baked on site each morning, good to eat by the river`}],why:`Independent riverside bakery and café by the Windrush, baking its own bread, pastries and cakes each day.`,tip:`Take a pastry to eat on the river bank; seats inside are limited.`,praise:[`Fresh pastries and good cream teas`,`Lovely spot right beside the river`,`Friendly, quick service`],watchOut:`Few tables, and queues build in the middle of the day.`,reservation:`walk-in`,reservationNote:`No bookings: order at the counter`},{id:`mousetrap-inn`,name:`The Mousetrap Inn`,area:`Bourton-on-the-Water (Lansdown)`,lat:51.88701,lng:-1.76179,kind:`bar`,meals:[`lunch`,`dinner`],spend:[15,30],order:[{name:`Pub classic of the day`,note:`Hearty dishes such as pie, burger or local sausages and mash`},{name:`Pint of local ale`,price:5,note:`Changing cask ales from Cotswold breweries`,wiki:`Real ale`}],why:`A traditional stone free house a few minutes from the busy centre, with changing local ales and honest pub food.`,tip:`A calmer choice than the riverside pubs, about a five-minute walk from the green.`,praise:[`Well-kept local ales`,`Generous, good-value pub dishes`,`Quieter than the pubs on the green`],reservation:`recommended`,reservationNote:`Book for dinner in summer and at weekends`},{id:`the-fox-oddington`,name:`The Fox at Oddington`,area:`Lower Oddington`,lat:51.94512,lng:-1.70592,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[25,55],order:[{name:`Wood-fired pizza`,note:`Baked in the wood-fired oven with produce from the Daylesford estate`,wiki:`Pizza`},{name:`Estate steak`,note:`Organic beef from the farm, cooked over fire`}],why:`Sister pub to Daylesford Organic, a flagstoned 19th-century inn cooking organic produce from the estate in a wood-fired oven.`,tip:`A short drive east of Stow; open all day, so it suits a late lunch after the farm shop.`,praise:[`Excellent organic ingredients`,`Beautifully restored country-inn setting`,`Relaxed, friendly service`],watchOut:`Priced like a smart restaurant rather than a village pub.`,reservation:`recommended`,reservationNote:`Book ahead for dinner and weekends`},{id:`eight-bells-chipping-campden`,name:`Eight Bells Inn`,area:`Chipping Campden (Church Street)`,lat:52.05229,lng:-1.77784,kind:`bar`,meals:[`lunch`,`dinner`],spend:[16,35],order:[{name:`Slow-cooked lamb`,note:`Local lamb, slow-cooked and served with seasonal vegetables`},{name:`Ploughman's lunch`,price:13,note:`Local cheese, ham, pickle and crusty bread`,wiki:`Ploughman's lunch`}],why:`A 14th-century inn first built for the masons of St James church, with beams, flagstones, open fires and local ales and ciders.`,tip:`Look for the old priest hole under the floor glass in the bar.`,praise:[`Cosy, characterful old inn`,`Hearty, well-cooked pub food`,`Good choice of local ales and ciders`],watchOut:`Small rooms fill up fast in the evening.`,reservation:`recommended`,reservationNote:`Book for dinner, especially Friday to Sunday`},{id:`russells-fish-and-chips`,name:`Russell's Fish & Chips`,area:`Broadway (High Street)`,lat:52.03635,lng:-1.86237,kind:`casual`,meals:[`lunch`,`dinner`],spend:[8,18],order:[{name:`Cod and chips`,price:14,note:`Fresh cod in crisp batter with thick-cut chips`,wiki:`Fish and chips`},{name:`Mushy peas and homemade tartare`,note:`The classic sides, made in-house`}],why:`A smart little chippy off Broadway High Street, run by the team behind the Russell's restaurant, frying fresh fish to eat in or take away.`,tip:`Take your fish and chips up to the village green or the bench by the war memorial.`,praise:[`Light, crisp batter and fresh fish`,`Generous portions`,`Good homemade tartare sauce`],watchOut:`Limited seating inside, so expect to take away at busy times.`,reservation:`walk-in`,reservationNote:`No bookings: order at the counter`},{id:`lamb-inn-burford`,name:`The Lamb Inn`,area:`Burford (Sheep Street)`,lat:51.80821,lng:-1.63935,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[20,55],order:[{name:`Seasonal tasting of the day`,note:`Refined British cooking using local and seasonal produce`},{name:`Afternoon tea`,price:35,note:`Sandwiches, scones and cakes served in the lounge or garden`,wiki:`Tea (meal)`}],why:`A 15th-century weavers' inn with flagstones, open fires and armchairs, serving lunch in the bar and more formal dinners overlooking the garden.`,tip:`Bar lunches are much cheaper than dinner in the restaurant.`,praise:[`Atmospheric old inn with log fires`,`Polished cooking in the restaurant`,`Pretty walled garden for summer`],watchOut:`Dinner in the restaurant is expensive.`,reservation:`recommended`,reservationNote:`Book for dinner; bar lunches are often walk-in`}],dishes:{"Cotswold Lamb":{price:[18,30],wiki:`Cotswold sheep`},"Cream Tea":{price:[9,16],wiki:`Cream tea`},"Double Gloucester Cheese":{price:[4,9],wiki:`Gloucester cheese`},"Gloucester Old Spot Pork":{price:[16,26],wiki:`Gloucestershire Old Spots`},"Sunday Roast":{price:[18,28],wiki:`Sunday roast`},"Fish and Chips":{price:[11,18],wiki:`Fish and chips`}}}},a=e({food:()=>o}),o={liverpool:{eateries:[{id:`maggie-mays-bold-street`,name:`Maggie May's`,area:`Ropewalks`,lat:53.40264,lng:-2.9778,kind:`cafe`,meals:[`breakfast`,`lunch`,`dinner`],spend:[7,14],order:[{name:`Scouse`,price:9,note:`Beef stew with potatoes and veg, served with red cabbage and bread`,wiki:`Scouse (food)`},{name:`Wet Nelly with custard`,price:5,note:`Syrupy spiced bread-pudding cake, served warm`}],why:`A no-frills café-bar on Bold Street that has long been a go-to for a proper bowl of scouse and other hearty Liverpool home cooking.`,tip:`Ask for the scouse with red cabbage and crusty bread; a vegetarian version, blind scouse, is usually on too.`,praise:[`Generous bowls of traditional scouse`,`Cheap, filling and quick`,`Friendly, down-to-earth service`],reservation:`walk-in`,reservationNote:`Just turn up; tables turn over quickly`},{id:`lucy-in-the-sky-cafe`,name:`Lucy in the Sky`,area:`Exchange`,lat:53.40747,lng:-2.99061,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[6,12],order:[{name:`Full English breakfast`,price:10,note:`Bacon, sausage, eggs, beans, mushrooms, tomato and toast`,wiki:`Full breakfast`},{name:`Scouse`,price:8,note:`A hearty bowl of the local meat and potato stew`,wiki:`Scouse (food)`}],why:`A cheerful Beatles-themed café near the business district, loved for big breakfasts, home-made scouse and budget prices.`,tip:`Daytime only, closing mid-afternoon; try the novelty milkshake served in a tiny wheelie bin.`,praise:[`Hearty breakfasts at very fair prices`,`Fun, colourful decor with Beatles music playing`,`Warm, chatty staff`],reservation:`walk-in`,reservationNote:`No bookings; grab any free table`},{id:`mowgli-bold-street`,name:`Mowgli Street Food`,area:`Ropewalks`,lat:53.40283,lng:-2.97751,kind:`casual`,meals:[`lunch`,`dinner`],spend:[18,30],order:[{name:`Yoghurt chat bombs`,price:7,note:`Crisp puri shells filled with spiced chickpeas, yoghurt and chutneys`,wiki:`Panipuri`},{name:`House lamb curry`,price:11,note:`Slow-cooked lamb in a homely, warmly spiced gravy`}],why:`The original branch of the Indian street-food chain founded in Liverpool, serving bright, home-style small plates on Bold Street.`,tip:`Order three or four small plates between two; there are good vegan options.`,praise:[`Vibrant, fresh-tasting Indian street food`,`Great for sharing lots of small plates`,`Fun, buzzy room with swings at some tables`],watchOut:`Small plates add up quickly, and it is noisy when full.`,reservation:`recommended`,reservationNote:`Book online for weekend evenings; walk-ins often fine at lunch`},{id:`maray-bold-street`,name:`Maray`,area:`Ropewalks`,lat:53.40245,lng:-2.97677,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[25,40],order:[{name:`Disco cauliflower`,price:8,note:`Roasted cauliflower with tahini, pomegranate and herbs`,wiki:`Cauliflower`},{name:`Falafel`,price:7,note:`Crisp chickpea fritters with dips`,wiki:`Falafel`}],why:`A small Bold Street favourite inspired by the food of Paris and Tel Aviv, serving creative Middle Eastern small plates and good cocktails.`,tip:`There is a second branch at the Albert Dock if Bold Street is full.`,praise:[`Inventive, flavour-packed vegetable dishes`,`Lively, cosy atmosphere`,`Well-made cocktails`],watchOut:`Tables are packed close together and the room is small.`,reservation:`recommended`,reservationNote:`Book for dinner, especially Thursday to Saturday`},{id:`lunya-liverpool`,name:`Lunya`,area:`Hanover Street`,lat:53.40361,lng:-2.98372,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[25,45],order:[{name:`Jamón ibérico`,price:14,note:`Hand-carved Iberian cured ham`,wiki:`Jamón ibérico`},{name:`Paella`,price:18,note:`Saffron rice pan dish cooked to order for two or more`,wiki:`Paella`}],why:`A long-running Catalan and Spanish tapas restaurant and deli, known for importing top-quality Spanish produce and wines.`,tip:`Browse the deli for Spanish ham, cheese and wine to take home.`,praise:[`Authentic tapas with excellent Spanish ingredients`,`Big choice for vegetarians and special diets`,`Knowledgeable staff and a strong wine list`],reservation:`recommended`,reservationNote:`Book for weekend evenings; weekday lunch usually walk-in`},{id:`ma-boyles-alehouse`,name:`Ma Boyle's Alehouse & Eatery`,area:`Exchange`,lat:53.40661,lng:-2.99432,kind:`bar`,meals:[`lunch`,`dinner`],spend:[12,22],order:[{name:`Scouse`,price:11,note:`Traditional stew of meat, potatoes and veg with red cabbage`,wiki:`Scouse (food)`},{name:`Fish and chips`,price:15,note:`Battered fish with chips and peas`,wiki:`Fish and chips`}],why:`A traditional pub in a historic building tucked behind the waterfront offices, serving real ales and pub classics including scouse.`,tip:`Handy between the Pier Head and the Cavern Quarter; quieter at weekends than city-centre pubs.`,praise:[`Old-fashioned pub with plenty of character`,`Solid, filling pub food at fair prices`,`Good choice of cask ales`],reservation:`walk-in`,reservationNote:`Order at the bar; book only for large groups`},{id:`the-pen-factory`,name:`The Pen Factory`,area:`Hope Street`,lat:53.40277,lng:-2.96952,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[22,40],order:[{name:`Seasonal small plates`,price:9,note:`Short daily-changing menu of modern British plates`},{name:`Sticky toffee pudding`,price:7,note:`Date sponge drenched in toffee sauce`,wiki:`Sticky toffee pudding`}],why:`A relaxed bar-restaurant on Hope Street from the team behind the old Everyman Bistro, with a short, seasonal menu and a pretty courtyard.`,tip:`Ideal before a show at the Everyman or the Philharmonic Hall next door.`,praise:[`Simple, well-cooked seasonal food`,`Laid-back atmosphere with a sheltered terrace`,`Thoughtful wine and beer list`],reservation:`recommended`,reservationNote:`Book before concerts and on weekends; otherwise walk-ins welcome`},{id:`panoramic-34`,name:`Panoramic 34`,area:`Exchange`,lat:53.40992,lng:-2.99662,kind:`fine`,meals:[`lunch`,`dinner`],spend:[50,90],order:[{name:`Tasting menu`,price:80,note:`Several modern European courses with river views`},{name:`Afternoon tea`,price:35,note:`Sandwiches, scones and cakes on the 34th floor`,wiki:`Tea (meal)`}],why:`One of the highest restaurants in the UK, on the 34th floor of the West Tower, with floor-to-ceiling views over the Mersey and the city.`,tip:`Book a sunset table on the river side; smart-casual dress expected.`,praise:[`Spectacular views across the Mersey and city`,`Polished service for a special occasion`,`Elegant cocktail lounge for a pre-dinner drink`],watchOut:`You pay a premium for the view, and drinks prices are high.`,reservation:`essential`,reservationNote:`Book at least a week ahead for weekends and window tables`}],dishes:{Scouse:{price:[7,13],wiki:`Scouse (food)`},"Fish and Chips":{price:[9,16],wiki:`Fish and chips`},"Salt and Pepper Chips":{price:[4,7],wiki:`Salt and pepper chips`},"Wet Nelly":{price:[3,6]},"Chip Butty":{price:[3,5],wiki:`Chip butty`},"Everton Mints":{price:[2,4]}}}},s=e({food:()=>c}),c={oxford:{eateries:[{id:`browns-cafe`,name:`Brown's Café`,area:`Covered Market (Avenue 4)`,lat:51.75303,lng:-1.25665,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[5,12],order:[{name:`Full English breakfast`,price:10,note:`Eggs, bacon, sausage, beans, mushrooms and toast with a mug of tea`,wiki:`Full breakfast`},{name:`Pastel de nata`,price:2,note:`Custard tart baked fresh each morning`,wiki:`Pastel de nata`}],why:`An old-fashioned family café in the Covered Market for about a century, serving big breakfasts and homely lunches at fair prices.`,tip:`Daytime only, closing mid-afternoon; the Market Street entrance is the closest.`,praise:[`Generous, no-nonsense breakfasts`,`Friendly, old-school atmosphere`,`Good value in the city centre`],watchOut:`Small and busy at weekend breakfast time, so expect to share tables.`,reservation:`walk-in`,reservationNote:`No bookings: grab a table and order`},{id:`sasis-thai`,name:`Sasi's Thai`,area:`Covered Market (Avenue 1)`,lat:51.75247,lng:-1.25684,kind:`street`,meals:[`lunch`],spend:[8,12],order:[{name:`Green curry with rice`,price:9,note:`Coconut green curry with chicken or tofu over jasmine rice`,wiki:`Green curry`},{name:`Pad thai`,price:9,note:`Stir-fried rice noodles with egg, peanuts and lime`,wiki:`Pad thai`}],why:`A tiny Covered Market counter dishing up home-style Thai curries and noodles in big portions at student prices.`,tip:`Daytime only and usually closed Sundays; eat at the shared market seating nearby.`,praise:[`Generous, flavourful curries`,`Very cheap for central Oxford`,`Quick service at lunchtime`],watchOut:`Lunchtime queues and very little seating of its own.`,reservation:`walk-in`,reservationNote:`No bookings: queue at the counter`},{id:`bens-cookies`,name:`Ben's Cookies`,area:`Covered Market (Market Street)`,lat:51.75238,lng:-1.25644,kind:`dessert`,meals:[`breakfast`,`lunch`],spend:[2,6],order:[{name:`Triple chocolate chunk cookie`,price:2,note:`Thick, gooey cookie sold warm by weight`,wiki:`Chocolate chip cookie`},{name:`Milk chocolate and hazelnut cookie`,note:`Soft-baked cookie packed with chunks of nuts and chocolate`}],why:`The original Ben's Cookies, which opened in the Covered Market in 1983 and grew into a chain; the cookies still come out of the oven all day.`,tip:`Takeaway only. Ask for one from the newest tray for the gooiest result.`,praise:[`Warm, soft cookies with huge chocolate chunks`,`A cheap, classic Oxford treat`],reservation:`walk-in`,reservationNote:`No bookings: order at the counter`},{id:`najars-place`,name:`Najar's Place`,area:`St Giles' (near the Martyrs' Memorial)`,lat:51.75575,lng:-1.25907,kind:`street`,meals:[`lunch`,`dinner`],spend:[4,8],order:[{name:`Falafel wrap`,price:5,note:`Freshly fried falafel with houmous and salads in a warm flatbread`,wiki:`Falafel`},{name:`Halloumi wrap`,note:`Grilled halloumi with mezze fillings of your choice`,wiki:`Halloumi`}],why:`A little blue food hut on St Giles' run by the same owner since 2005, famous among students for fresh, filling falafel wraps.`,tip:`Open daily until early evening; eat on the steps of the Martyrs' Memorial a few metres away.`,praise:[`Hefty wraps for very little money`,`Fresh falafel fried to order`,`Warm, chatty owner`],watchOut:`Takeaway only, and the queue can be long at lunchtime.`,reservation:`walk-in`,reservationNote:`No bookings: queue at the hut`},{id:`the-grand-cafe`,name:`The Grand Café`,area:`High Street`,lat:51.75248,lng:-1.25058,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[8,25],order:[{name:`Cream tea`,price:8,note:`Scones with clotted cream and jam and a pot of tea`,wiki:`Cream tea`},{name:`Grand high tea`,price:17,note:`Sandwiches, scones and sweets, with a glass of fizz`,wiki:`Tea (meal)`}],why:`On the site of England's first coffee house, opened in 1650, now a gilded café with marble columns serving afternoon tea.`,tip:`Afternoon tea is served roughly 2pm to 5pm; it is opposite Queen's College on the High.`,praise:[`Opulent, historic setting`,`Good-value afternoon tea for Oxford`,`Central and easy to drop into`],watchOut:`Small and often full at teatime, and some find the décor a little overdone.`,reservation:`recommended`,reservationNote:`Book afternoon tea at weekends; weekdays are often walk-in`},{id:`kings-arms`,name:`King's Arms`,area:`Holywell Street (by the Weston Library)`,lat:51.75508,lng:-1.25432,kind:`bar`,meals:[`lunch`,`dinner`],spend:[15,25],order:[{name:`Fish and chips`,price:18,note:`Beer-battered fish with chips, peas and tartare sauce`,wiki:`Fish and chips`},{name:`Pint of real ale`,price:6,note:`Cask ale from the Young's range and guest breweries`,wiki:`Real ale`}],why:`A rambling 17th-century pub at the corner of Holywell and Parks Road, a student and academic haunt with classic pub food.`,tip:`Order at the bar; the back rooms are quieter. Busy with students on term-time evenings.`,praise:[`Atmospheric warren of old rooms`,`Reliable pub classics`,`Handy for the Bodleian and Sheldonian`],watchOut:`Very crowded in the evenings and pricey for pub food.`,reservation:`walk-in`,reservationNote:`Order at the bar; tables are first come, first served`},{id:`gees`,name:`Gee's`,area:`North Oxford (Banbury Road)`,lat:51.7643,lng:-1.26122,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`],spend:[26,45],order:[{name:`Seasonal Mediterranean plates`,note:`Small plates such as croquetas, octopus and burrata to share`},{name:`Weekend brunch`,note:`Brunch served daily from 9am to 11am`}],why:`A Victorian glasshouse that was once a florist, now a light-filled restaurant serving Mediterranean-style seasonal food.`,tip:`A 15-minute walk north from the centre. Ask for a table under the glass roof.`,praise:[`Beautiful conservatory setting`,`Seasonal, well-made dishes`,`Lovely for a long lunch or brunch`],watchOut:`On the expensive side, and service can slow when it is full.`,reservation:`recommended`,reservationNote:`Book online for dinner and weekend brunch`},{id:`branca`,name:`Branca`,area:`Jericho (Walton Street)`,lat:51.76073,lng:-1.26674,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[18,35],order:[{name:`Wood-fired pizza`,price:15,note:`Thin, blistered pizza from the oven with Italian toppings`,wiki:`Neapolitan pizza`},{name:`Fresh pasta of the day`,note:`Seasonal pasta dish from the daily menu`}],why:`A long-running, airy Italian restaurant in Jericho with a deli next door, popular with locals before a film at the Phoenix.`,tip:`Lunch is weekends only; dinner Wednesday to Sunday. The deli sells good picnic supplies for Port Meadow.`,praise:[`Relaxed, roomy neighbourhood spot`,`Good pizza and pasta`,`Handy for an evening in Jericho`],reservation:`recommended`,reservationNote:`Book for Friday and Saturday evenings`},{id:`cherwell-boathouse`,name:`Cherwell Boathouse`,area:`North Oxford (Bardwell Road)`,lat:51.76963,lng:-1.25377,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[30,55],order:[{name:`Seasonal set menu`,note:`Modern British dishes changing with the seasons`},{name:`Wine from the long list`,note:`An award-winning cellar at fair mark-ups`}],why:`A riverside restaurant at a Victorian punt station on the Cherwell, known for seasonal cooking and a much-loved wine list.`,tip:`Combine with a punt hired from the station outside. Closed some weekday lunchtimes, so check ahead.`,praise:[`Idyllic riverside setting`,`Excellent wine list`,`Thoughtful seasonal cooking`],watchOut:`A taxi or 25-minute walk from the centre, and prices are special-occasion level.`,reservation:`recommended`,reservationNote:`Book ahead for dinner and sunny weekends, especially for terrace tables`}],dishes:{"Oxford Sausage":{price:[4,12],wiki:`Oxford sausage`},"Oxford Marmalade":{price:[3,6],wiki:`Frank Cooper's`},"Cream Tea":{price:[8,15],wiki:`Cream tea`},"Sunday Roast":{price:[17,25],wiki:`Sunday roast`},"Fish and Chips":{price:[11,20],wiki:`Fish and chips`},"Real Ale":{price:[5,7],wiki:`Real ale`}}}},l=e({food:()=>u}),u={york:{eateries:[{id:`bettys-st-helens-square`,name:`Bettys Café Tea Rooms`,area:`St Helen's Square`,lat:53.96012,lng:-1.08422,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[15,40],order:[{name:`Fat Rascal`,price:6,note:`Large, rich fruit scone with citrus peel, decorated with cherries and almonds`,wiki:`Fat rascal`},{name:`Yorkshire rarebit`,price:17,note:`Cheese and ale sauce grilled on toast, served with ham`},{name:`Afternoon tea`,price:40,note:`Sandwiches, scones with jam and cream, and cakes with a pot of tea`,wiki:`Tea (meal)`}],why:`The York branch of the century-old Yorkshire tea room family, in Art Deco rooms inspired by the Queen Mary liner, baking its own cakes and breads.`,tip:`No bookings for the main café; queue before 10am, or buy cakes from the shop counter to take away.`,praise:[`Elegant Art Deco tea room with polished, traditional service`,`Fat Rascals and cakes baked in their own Yorkshire bakery`,`A memorable treat for afternoon tea`],watchOut:`Expensive for a café, and queues outside can be long at weekends and in holidays.`,reservation:`walk-in`,reservationNote:`Queue for the main café; only the separate afternoon tea room takes bookings`},{id:`brew-and-brownie`,name:`Brew & Brownie`,area:`Museum Street`,lat:53.96105,lng:-1.08563,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[7,16],order:[{name:`Pancake stack`,price:11,note:`Thick fluffy pancakes stacked with toppings such as bacon, berries or syrup`,wiki:`Pancake`},{name:`Chocolate brownie`,price:4,note:`Dense, fudgy chocolate square, baked in house`,wiki:`Chocolate brownie`}],why:`A popular independent café by the Museum Gardens known for big breakfasts, pancake stacks and rich home-made brownies.`,tip:`No reservations and often a queue at weekends; go early or mid-afternoon.`,praise:[`Generous, well-made brunch plates`,`Rich, gooey brownies and good coffee`,`Friendly, relaxed service`],reservation:`walk-in`,reservationNote:`No bookings: just turn up and join the queue`},{id:`york-roast-co`,name:`The York Roast Co`,area:`Low Petergate`,lat:53.96042,lng:-1.0805,kind:`street`,meals:[`lunch`],spend:[7,12],order:[{name:`Yorkshire pudding wrap`,price:11,note:`A giant flat Yorkshire pudding rolled around roast meat, stuffing and gravy`,wiki:`Yorkshire pudding`},{name:`Roast pork sandwich with crackling`,price:8,note:`Carved roast pork in a bread roll with crackling, stuffing and apple sauce`}],why:`A takeaway carvery near the Shambles that turns a full roast dinner into a sandwich, or into its famous Yorkshire pudding wrap.`,tip:`Takeaway only with a few stools; eat it in the Minster gardens nearby.`,praise:[`Novel Yorkshire pudding wrap that packs in a whole roast dinner`,`Big, filling portions for the price`,`Quick service in the heart of the old city`],watchOut:`Messy to eat on the go, and lunchtime queues are common in peak season.`,reservation:`walk-in`,reservationNote:`Order at the counter; takeaway`},{id:`shambles-food-court`,name:`Shambles Market Food Court`,area:`Shambles`,lat:53.95931,lng:-1.08061,kind:`market`,meals:[`breakfast`,`lunch`],spend:[6,12],order:[{name:`Street food from the stalls`,price:8,note:`Pick from changing stalls: roast pork rolls, burgers, curries and more`},{name:`Coffee and a cake`,price:5,note:`A hot drink and a slice of cake from one of the café stalls`}],why:`A covered cluster of independent street-food stalls at the end of the daily market, from roast pork rolls to global dishes.`,tip:`Stalls vary by day and most close by late afternoon; seating is shared and open-sided.`,praise:[`Wide variety of cheap independent food stalls`,`Handy, casual stop right by the Shambles`,`Easy for groups who all want something different`],reservation:`walk-in`,reservationNote:`Order at each stall and grab any free seat`},{id:`pig-and-pastry`,name:`The Pig & Pastry`,area:`Bishopthorpe Road`,lat:53.95136,lng:-1.08525,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[7,15],order:[{name:`Full breakfast`,price:12,note:`Bacon, sausage, eggs, beans, mushrooms, tomato and toast`,wiki:`Full breakfast`},{name:`Bacon sandwich`,price:7,note:`Thick bacon rashers in bread, with butter and sauce of your choice`,wiki:`Bacon sandwich`}],why:`A long-running neighbourhood café on lively Bishopthorpe Road, loved locally for generous breakfasts and home baking.`,tip:`A 15-minute walk south of the centre; pair it with a stroll in nearby Rowntree Park.`,praise:[`Hearty, good-quality breakfasts`,`Home-made cakes and bakes`,`Cosy neighbourhood feel away from the tourist centre`],watchOut:`Small and busy at weekend brunch, so expect to wait for a table.`,reservation:`walk-in`,reservationNote:`No booking needed; arrive before 10am at weekends to avoid a wait`},{id:`drakes-fish-and-chips`,name:`Drake's Fish & Chips`,area:`Low Petergate`,lat:53.96038,lng:-1.08071,kind:`casual`,meals:[`lunch`,`dinner`],spend:[10,22],order:[{name:`Haddock and chips`,price:14,note:`Battered, deep-fried haddock with thick-cut chips, the Yorkshire favourite`,wiki:`Fish and chips`},{name:`Mushy peas`,price:2,note:`Soft, mashed dried marrowfat peas, the classic chip-shop side`,wiki:`Mushy peas`}],why:`A family-run chippy in the shadow of the Minster, frying traditional Yorkshire fish and chips with a sit-down restaurant and takeaway.`,tip:`Takeaway is cheaper than eating in; open daily from late morning into the evening.`,praise:[`Crisp, light batter on fresh haddock`,`Convenient spot right by the Minster`,`Classic chip-shop sides done well`],watchOut:`Busy at peak meal times with tourists, so the takeaway queue can be long.`,reservation:`walk-in`,reservationNote:`Walk in for a table, or queue at the takeaway counter`},{id:`skosh`,name:`Skosh`,area:`Micklegate`,lat:53.95685,lng:-1.08958,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[35,60],order:[{name:`Skosh fried chicken`,price:8,note:`The house fried chicken, a crisp signature small plate`},{name:`Seasonal small plates`,price:10,note:`Changing sharing plates built on Yorkshire produce with global flavours`}],why:`Chef Neil Bentinck's small-plates restaurant mixing Yorkshire produce with Japanese, Indian and Middle Eastern flavours.`,tip:`Book well ahead, especially for weekends; open Wednesday to Sunday.`,praise:[`Inventive small plates with bold, well-balanced flavours`,`Relaxed, friendly service and a buzzy room`,`Creative use of local Yorkshire ingredients`],watchOut:`Small plates add up quickly, so the bill can climb if you order freely.`,reservation:`recommended`,reservationNote:`Book weeks ahead for Friday or Saturday; midweek tables are easier to find`},{id:`roots-york`,name:`Roots`,area:`Marygate`,lat:53.96178,lng:-1.09062,kind:`fine`,meals:[`lunch`,`dinner`],spend:[80,140],order:[{name:`Seasonal set menu`,price:85,note:`Multi-course menu built around produce from the Banks family farm`}],why:`Tommy Banks' restaurant in a former pub by the Museum Gardens, cooking menus built around produce from his family farm at Oldstead.`,tip:`Book weeks ahead; menus follow the farm seasons and dietary needs need notice.`,praise:[`Creative cooking that showcases farm-grown Yorkshire produce`,`Relaxed, warm service for a fine-dining restaurant`,`Menus that change with the farm seasons`],watchOut:`A special-occasion price, with drinks pairings adding considerably.`,reservation:`essential`,reservationNote:`Reserve weeks ahead, longer for Saturday dinner; walk-ins are not realistic`}],dishes:{"Yorkshire Pudding":{price:[4,12],wiki:`Yorkshire pudding`},"Fish and Chips":{price:[9,18],wiki:`Fish and chips`},"Fat Rascal":{price:[4,7],wiki:`Fat rascal`},"Yorkshire Curd Tart":{price:[3,6]},Parkin:{price:[2,5],wiki:`Parkin (cake)`},"Wensleydale Cheese with Fruit Cake":{price:[4,9],wiki:`Wensleydale cheese`}}}},d=e({food:()=>f}),f={london:{eateries:[{id:`borough-market`,name:`Borough Market`,area:`London Bridge`,lat:51.50553,lng:-.09044,kind:`market`,meals:[`breakfast`,`lunch`],spend:[10,25],order:[{name:`Raclette or toasted cheese sandwich`,price:10,note:`Melted Alpine cheese scraped over potatoes, or a griddled cheese toastie`,wiki:`Raclette`},{name:`Scotch egg`,price:6,note:`Boiled egg wrapped in sausage meat, breadcrumbed and fried`,wiki:`Scotch egg`},{name:`Custard doughnut`,price:4,note:`Sugared yeast doughnut filled with vanilla custard`}],why:`London's best-known food market, trading by London Bridge for centuries, with dozens of stalls for cheese, bakes, street food and fresh produce.`,tip:`Go before noon to beat the crowds; some traders are closed on Mondays and the market is shut on Sundays.`,praise:[`Huge variety of high-quality produce and street food in one place`,`Generous free tasters from cheese and bakery stalls`,`Atmospheric Victorian halls beside Southwark Cathedral`],watchOut:`Shoulder-to-shoulder crowds at weekend lunchtimes, and prices are high for street food.`,reservation:`walk-in`,reservationNote:`No booking: wander the stalls and eat standing or at shared benches`},{id:`beigel-bake`,name:`Beigel Bake`,area:`Brick Lane, Shoreditch`,lat:51.52451,lng:-.07175,kind:`bakery`,meals:[`breakfast`,`lunch`,`late`],spend:[3,8],order:[{name:`Salt beef beigel with mustard`,price:8,note:`Thick slices of hot salt-cured brisket in a chewy bagel with hot mustard`},{name:`Smoked salmon and cream cheese beigel`,price:4,note:`Bagel filled with smoked salmon and cream cheese`}],why:`A round-the-clock East End bakery on Brick Lane, famous for hand-carved hot salt beef in chewy beigels at very low prices.`,tip:`Open 24 hours; expect a queue late on weekend nights. Card machines can be patchy, so carry some cash.`,praise:[`Generously stuffed salt beef beigels carved to order`,`Remarkably cheap, especially for London`,`Open all night, a late-night institution`],watchOut:`Brusque, fast service and no seating; it is strictly a grab-and-go counter.`,reservation:`walk-in`,reservationNote:`Queue at the counter; takeaway only`},{id:`m-manze-tower-bridge`,name:`M.Manze`,area:`Tower Bridge Road, Bermondsey`,lat:51.49634,lng:-.08275,kind:`casual`,meals:[`lunch`],spend:[6,12],order:[{name:`Pie, mash and liquor`,price:7,note:`Minced beef pie with mashed potato and green parsley sauce called liquor`,wiki:`Pie and mash`},{name:`Stewed or jellied eels`,price:6,note:`Chopped eels, served warm in sauce or cold set in their own jelly`,wiki:`Jellied eels`}],why:`Run by the Manze family since 1902 and widely called London's oldest surviving pie and mash shop, with its original tiles and wooden booths.`,tip:`Lunchtime hours only and closed on Sundays; add chilli vinegar to your pie the traditional way.`,praise:[`Authentic East End pie and mash at very low prices`,`Beautiful original tiled interior and wooden booths`,`Friendly, no-nonsense service`],reservation:`walk-in`,reservationNote:`No bookings: order at the counter and take a free booth`},{id:`poppies-spitalfields`,name:`Poppies Fish & Chips`,area:`Spitalfields`,lat:51.5202,lng:-.0729,kind:`casual`,meals:[`lunch`,`dinner`],spend:[15,25],order:[{name:`Cod and chips with mushy peas`,price:18,note:`Battered fried cod and chips with a side of mushed marrowfat peas`,wiki:`Fish and chips`},{name:`Haddock and chips`,price:19,note:`Battered fried haddock with thick-cut chips`,wiki:`Fish and chips`}],why:`A retro 1950s-style chippy near Spitalfields Market from veteran East End fryer Pop Newland, with fish prepared by an in-house fishmonger.`,tip:`Busy at weekend lunch; takeaway is quicker and cheaper than eating in.`,praise:[`Fresh fish in crisp, golden batter`,`Fun retro 1950s decor and jukebox styling`,`Friendly service and generous portions`],watchOut:`Pricier than a typical local chippy, especially when eating in.`,reservation:`walk-in`,reservationNote:`Walk in for a table, or order takeaway at the counter`},{id:`dishoom-covent-garden`,name:`Dishoom`,area:`Covent Garden`,lat:51.51243,lng:-.12686,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`],spend:[20,40],order:[{name:`Bacon naan roll`,price:12,note:`Smoked streaky bacon in a fresh naan with cream cheese, chilli jam and herbs`},{name:`House black daal`,price:10,note:`Black lentils simmered for many hours with butter and cream`,wiki:`Dal makhani`},{name:`Chicken ruby`,price:17,note:`Tender chicken in a rich, mildly spiced tomato and butter curry`}],why:`The first branch (2010) of the Bombay-café-style group, loved for its breakfast bacon naan rolls and slow-cooked black daal.`,tip:`Breakfast is the easiest time to get in; dinner queues can be long, though small groups can book ahead.`,praise:[`Rich, slow-cooked black daal that many diners rave about`,`Atmospheric Bombay-café styling`,`Warm, efficient service even when very busy`],watchOut:`Long evening waits for walk-ins, and the room is loud and busy.`,reservation:`recommended`,reservationNote:`Book online for dinner; breakfast and mid-afternoon are easiest as walk-ins`},{id:`padella-borough`,name:`Padella`,area:`Borough Market`,lat:51.50513,lng:-.08991,kind:`casual`,meals:[`lunch`,`dinner`],spend:[15,30],order:[{name:`Pici cacio e pepe`,price:9,note:`Thick hand-rolled Tuscan noodles in a pecorino and black pepper sauce`,wiki:`Cacio e pepe`},{name:`Pappardelle with beef shin ragu`,price:14,note:`Wide ribbon pasta with a slow-cooked beef shin sauce`}],why:`A small, fast-paced pasta bar by Borough Market serving fresh hand-made pasta at modest prices since 2016.`,tip:`No bookings: join the virtual queue via the app or in person and wait in a nearby pub.`,praise:[`Silky fresh pasta at prices hard to beat in London`,`Pici cacio e pepe and beef shin pappardelle are standouts`,`Quick, buzzy service`],watchOut:`Not a place to linger; tables turn fast and the counter seats are tight.`,reservation:`walk-in`,reservationNote:`No bookings: add your name to the queue and expect a wait at peak times`},{id:`st-john-smithfield`,name:`St. JOHN`,area:`Smithfield, Clerkenwell`,lat:51.52048,lng:-.10127,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[45,80],order:[{name:`Roast bone marrow and parsley salad`,price:13,note:`Roasted marrow bones with toast, sea salt and a sharp parsley and caper salad`,wiki:`Bone marrow (food)`},{name:`Eccles cake with Lancashire cheese`,price:10,note:`Flaky currant-filled pastry served with crumbly Lancashire cheese`,wiki:`Eccles cake`},{name:`Madeleines`,price:7,note:`Small shell-shaped sponge cakes, baked to order and served warm`,wiki:`Madeleine (cake)`}],why:`Fergus Henderson's whitewashed former smokehouse, open since 1994 and known for nose-to-tail British cooking.`,tip:`Book for the dining room, or drop into the bar for bread, a glass of wine and a few small plates.`,praise:[`Iconic roast bone marrow and parsley salad`,`Simple, confident British cooking with offal done well`,`Warm madeleines and Eccles cake to finish`],watchOut:`Stark, plain dining room and a meat-heavy menu with limited vegetarian choice.`,reservation:`recommended`,reservationNote:`Book the dining room a few days ahead; the bar takes walk-ins`},{id:`the-wolseley`,name:`The Wolseley`,area:`Piccadilly`,lat:51.50739,lng:-.14091,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`],spend:[30,60],order:[{name:`Full English breakfast`,price:22,note:`Eggs, bacon, sausage, black pudding, mushrooms, tomato, beans and toast`,wiki:`Full breakfast`},{name:`Afternoon tea`,price:45,note:`Finger sandwiches, scones with clotted cream and jam, and pastries with tea`,wiki:`Tea (meal)`},{name:`Viennoiserie basket`,price:12,note:`A selection of croissants and other buttery breakfast pastries`,wiki:`Viennoiserie`}],why:`A grand European-style café in a 1920s former car showroom next to the Ritz, serving breakfast and afternoon tea all day since 2003.`,tip:`Book breakfast or afternoon tea a week or more ahead; smart-casual dress suits the room.`,praise:[`Spectacular high-ceilinged dining room with real glamour`,`Polished, attentive service`,`A classic London breakfast in grand surroundings`],watchOut:`Expensive for what is largely brasserie food; you are paying for the room.`,reservation:`recommended`,reservationNote:`Book ahead for weekend breakfast and tea; weekday off-peak walk-ins can work`}],dishes:{"Fish and Chips":{price:[12,20],wiki:`Fish and chips`},"Sunday Roast":{price:[18,28],wiki:`Sunday roast`},"Full English Breakfast":{price:[10,18],wiki:`Full breakfast`},"Pie and Mash":{price:[5,10],wiki:`Pie and mash`},"Afternoon Tea":{price:[35,70],wiki:`Tea (meal)`},"Chicken Tikka Masala":{price:[12,18],wiki:`Chicken tikka masala`}}},edinburgh:{eateries:[{id:`oink-victoria-street`,name:`Oink`,area:`Victoria Street, Old Town`,lat:55.9486,lng:-3.1931,kind:`street`,meals:[`lunch`],spend:[5,9],order:[{name:`Hog roast roll with haggis`,price:7,note:`Slow-roasted pork carved into a soft roll, topped with haggis and sauce`,wiki:`Hog roast`},{name:`Piglet (small roll)`,price:5,note:`A smaller roll of the same hog roast pork, for a lighter bite`}],why:`A farm-run hog roast shop that has carved whole roast pigs into crusty rolls on Victoria Street for over 25 years.`,tip:`Takeaway only and closes when the pig runs out, usually late afternoon.`,praise:[`Juicy, tender pork carved straight from the whole pig`,`Cheap, filling lunch on a scenic Old Town street`,`Haggis and crackling toppings add a Scottish touch`],reservation:`walk-in`,reservationNote:`Order at the counter; takeaway only`},{id:`mums-great-comfort-food`,name:`Mums Great Comfort Food`,area:`Forrest Road, Old Town`,lat:55.946,lng:-3.1916,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[12,20],order:[{name:`Sausage, mash and gravy`,price:13,note:`Choice of sausages on mashed potato with a choice of gravy`,wiki:`Bangers and mash`},{name:`Full Scottish breakfast`,price:12,note:`Fried breakfast with additions such as haggis, black pudding and tattie scone`,wiki:`Full breakfast`},{name:`Haggis, neeps and tatties`,price:12,note:`Spiced sheep offal pudding with mashed swede and mashed potato`,wiki:`Haggis`}],why:`A long-running, unfussy café near Greyfriars serving British comfort food from local suppliers, with a pick-and-mix menu of sausages, mash and gravy.`,tip:`Small and popular with students; come early for breakfast or expect a short wait.`,praise:[`Hearty, filling comfort food at fair prices`,`Fun mix-and-match sausage, mash and gravy menu`,`Retro, homely and relaxed setting`],reservation:`walk-in`,reservationNote:`No booking needed: walk in, with a short wait at peak times`},{id:`marys-milk-bar`,name:`Mary's Milk Bar`,area:`Grassmarket`,lat:55.94738,lng:-3.19654,kind:`dessert`,meals:[`lunch`],spend:[4,8],order:[{name:`Gelato of the day`,price:4,note:`Small-batch Italian-style ice cream in daily changing flavours`,wiki:`Gelato`},{name:`Hot chocolate float`,price:6,note:`Rich hot chocolate with a scoop of gelato melting on top`}],why:`A tiny retro gelato and chocolate shop on the Grassmarket with castle views, making small batches of changing flavours daily.`,tip:`Short opening days (typically Wednesday to Sunday) and frequent queues on sunny afternoons.`,praise:[`Creative, changing gelato flavours made in small batches`,`Signature hot chocolate float`,`Charming retro shop with a view of the castle`],watchOut:`Very small, with almost no seating, so plan to eat your gelato outside.`,reservation:`walk-in`,reservationNote:`Queue at the counter and take your gelato outside`},{id:`edinburgh-farmers-market`,name:`Edinburgh Farmers' Market`,area:`Castle Terrace`,lat:55.9474,lng:-3.2033,kind:`market`,meals:[`breakfast`,`lunch`],spend:[6,15],order:[{name:`Hot rolls and street food`,price:7,note:`Hot rolls such as venison burgers or bacon, plus changing street food`},{name:`Scottish cheese and smoked fish to take away`,price:8,note:`Farmhouse cheeses and smoked salmon or trout from Scottish producers`}],why:`A weekly producers' market beneath the castle with Scottish meat, fish, cheese, bakes and hot street food stalls.`,tip:`Saturdays only, roughly 9am to 2pm; entry is free.`,praise:[`Excellent Scottish produce sold by the makers themselves`,`Superb castle backdrop`,`Tasty hot food for a market breakfast or lunch`],reservation:`walk-in`,reservationNote:`Just turn up and buy from the stalls`},{id:`scran-and-scallie`,name:`The Scran & Scallie`,area:`Stockbridge`,lat:55.9596,lng:-3.2138,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[25,45],order:[{name:`Haggis, neeps and tatties`,price:17,note:`Haggis with mashed swede and potato, usually with a whisky sauce`,wiki:`Haggis`},{name:`Steak pie`,price:22,note:`Slow-cooked beef in gravy under a puff pastry lid`,wiki:`Steak pie`},{name:`Cranachan`,price:9,note:`Whipped cream, raspberries, honey, toasted oats and whisky`,wiki:`Cranachan`}],why:`A Stockbridge gastropub from chef Tom Kitchin, open since 2013, serving Scottish pub classics made with seasonal local produce.`,tip:`Book for weekend lunch and Sunday roast; family-friendly with a children's corner.`,praise:[`Elevated Scottish pub classics with quality local produce`,`Cosy, welcoming room that suits families`,`Well-executed haggis and steak pie`],watchOut:`Pricier than a typical pub, and weekend tables go fast.`,reservation:`recommended`,reservationNote:`Book for weekends and Sunday lunch; weekday walk-ins are often fine`},{id:`the-fishmarket-newhaven`,name:`The Fishmarket`,area:`Newhaven Harbour`,lat:55.9811,lng:-3.1947,kind:`casual`,meals:[`lunch`,`dinner`],spend:[15,30],order:[{name:`Haddock and chips`,price:15,note:`Fresh battered haddock and chips`,wiki:`Fish and chips`},{name:`Smoked haddock chowder`,price:9,note:`Creamy soup of smoked haddock, potato and onion`},{name:`Oysters`,price:3,note:`Fresh oysters served raw on the half shell`,wiki:`Oyster`}],why:`A seafood restaurant and chippy in Newhaven's old harbour fish market, opened in 2018 by chef Roy Brett and a local fishmonger.`,tip:`Small dining room, so book at weekends; fish and chips are also sold to take away to the harbour.`,praise:[`Very fresh fish with light, crisp batter`,`Lovely harbour-side setting`,`Good seafood beyond the chippy classics`],watchOut:`A bus or long walk from the centre.`,reservation:`recommended`,reservationNote:`Book for a weekend sit-down meal; takeaway needs no booking`},{id:`the-kitchin`,name:`The Kitchin`,area:`The Shore, Leith`,lat:55.977,lng:-3.1724,kind:`fine`,meals:[`lunch`,`dinner`],spend:[90,200],order:[{name:`Set lunch menu`,price:55,note:`A shorter fixed-price menu of seasonal Scottish dishes`},{name:`Seasonal tasting menu`,price:150,note:`Multi-course menu showcasing Scottish seafood, game and vegetables`}],why:`Tom Kitchin's waterfront restaurant in a converted Leith whisky warehouse since 2006, with a "from nature to plate" focus on Scottish produce.`,tip:`Book weeks ahead; the set lunch is the most affordable way in. Closed Sundays and Mondays.`,praise:[`Superb Scottish seafood and game, beautifully cooked`,`Polished, attentive service`,`Seasonal menus with a strong sense of place`],watchOut:`Very expensive in the evening, especially with wine.`,reservation:`essential`,reservationNote:`Reserve weeks ahead, especially for Friday and Saturday dinner`}],dishes:{"Haggis, Neeps and Tatties":{price:[10,18],wiki:`Haggis`},"Cullen Skink":{price:[7,12],wiki:`Cullen skink`},Cranachan:{price:[6,10],wiki:`Cranachan`},"Scotch Pie":{price:[2,4],wiki:`Scotch pie`},"Full Scottish Breakfast":{price:[9,15],wiki:`Full breakfast`},Tablet:{price:[2,5],wiki:`Tablet (confectionery)`}}}};export{r as a,a as i,l as n,t as o,s as r,d as t};